import json
from unittest.mock import patch
from experiments.argo_workflow_followup.public_ml_apparatus.house_price_runtime.test_combination_capsule import SyntheticCapsuleTest
import experiments.argo_workflow_followup.public_ml_apparatus.house_price_runtime.combination_capsule as capsule
from experiments.argo_workflow_followup.public_ml_apparatus.house_price_runtime.source_closure import capture_tree
results={}
case=SyntheticCapsuleTest("test_exact_capsule_has_twenty_five_sources_and_four_empty_initializers");case.setUp()
try:
 out=case.root/"profile"/"synthetic";rejected=False
 try:capsule.materialize_synthetic_capsule(out,case.members,protected_roots=case.protected)
 except capsule.SyntheticCapsuleError:rejected=True
 results["protected_profile_parent"]={"rejected":rejected,"destination_created":out.exists()}
finally:case.tearDown()
case=SyntheticCapsuleTest("test_exact_capsule_has_twenty_five_sources_and_four_empty_initializers");case.setUp()
try:
 target=case.destination/case.members[0].relative_path
 def mutate(path,limits):
  data=target.read_bytes();target.write_bytes(bytes([data[0]^1])+data[1:]);return capture_tree(path,limits)
 rejected=False
 try:
  with patch.object(capsule,"capture_tree",side_effect=mutate):capsule.materialize_synthetic_capsule(case.destination,case.members,protected_roots=case.protected)
 except capsule.SyntheticCapsuleError:rejected=True
 results["late_same_size_tamper"]={"rejected":rejected,"partial_destination_retained":case.destination.exists()}
finally:case.tearDown()
print(json.dumps(results,sort_keys=True,indent=2))
